#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
UI-UX Custom Colors: 2 sliders (Primaria, Secundaria) na tela XaulinXs
Customizations que geram, via HCT (Material You real, sem dependencia
nova -- usa androidx.core.graphics.ColorUtils.colorToM3HCT/M3HCTToColor,
ja em uso no projeto), a paleta tonal completa (30 chaves) e aplicam em
TODO o app.

Como reescrever o XML empacotado no APK nao e possivel em runtime (sem
root), a aplicacao acontece por INTERCEPTACAO de leitura, nao por
reescrita de arquivo: um Resources/ContextWrapper (XaulinXsThemeColorResources.kt)
substitui getColor()/getColorStateList() para os 30 IDs materialColorX,
instalado em attachBaseContext (LauncherApplication + Launcher +
SettingsActivity + a propria CustomColorsActivity -- Activity.getResources()
nao herda do wrapper da Application, por isso os 4 pontos). Cobre os
~46 arquivos (drawable XML, layout XML, codigo Kotlin/Java) que hoje
consomem @color/materialColorX SEM TOCAR em nenhum deles.

Arquivos criados:
  modules/customizations/.../theme/XaulinXsColorPalette.kt
  modules/customizations/.../theme/XaulinXsThemeColorResources.kt
  modules/customizations/.../settings/CustomColorsActivity.kt

Arquivos editados (patch cirurgico, cada um com marcador de idempotencia):
  src/com/android/launcher3/LauncherApplication.java
  src/com/android/launcher3/Launcher.java
  src/com/android/launcher3/settings/SettingsActivity.java
  AndroidManifest.xml
  res/xml/launcher_preferences.xml
  res/values/xaulinxs_strings.xml

Rode este script na RAIZ do checkout local do repo (mesmo diretorio do
gradlew), dentro do Termux.

python3 apply_custom_colors.py

Idempotente: roda de novo sem duplicar nada.
"""
import base64
import sys
from pathlib import Path

def die(msg):
    print("ERRO:", msg)
    sys.exit(1)

if not Path("gradlew").exists():
    die("rode este script na raiz do checkout (onde esta o gradlew).")

# ---------------------------------------------------------------------------
# 1) Arquivos novos (criados via base64 -- conteudo binario-safe)
# ---------------------------------------------------------------------------
NEW_FILES = {
    "modules/customizations/src/com/xaulinxs/customizations/theme/XaulinXsColorPalette.kt": """""",
    "modules/customizations/src/com/xaulinxs/customizations/theme/XaulinXsThemeColorResources.kt": """""",
    "modules/customizations/src/com/xaulinxs/customizations/settings/CustomColorsActivity.kt": """""",
}

created, skipped_new = [], []
for rel_path, b64 in NEW_FILES.items():
    target = Path(rel_path)
    content = base64.b64decode(b64).decode("utf-8")
    if target.exists():
        existing = target.read_text(encoding="utf-8")
        if existing == content:
            skipped_new.append(rel_path)
            continue
        else:
            die(
                f"{rel_path} ja existe com conteudo DIFERENTE do esperado. "
                "Pode ter sido editado manualmente ou por outra versao do "
                "script. Abortando sem sobrescrever -- me manda o conteudo "
                "atual do arquivo que eu ajusto o patch."
            )
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    created.append(rel_path)

# ---------------------------------------------------------------------------
# 2) Patches ciruzgicos em arquivos existentes
# ---------------------------------------------------------------------------
PATCHES = [
    (
        "src/com/android/launcher3/LauncherApplication.java",
        'import android.app.Application;\nimport com.android.launcher3.dagger.DaggerLauncherAppComponent;\nimport com.android.launcher3.dagger.LauncherAppComponent;\nimport com.android.launcher3.dagger.LauncherBaseAppComponent;\nimport com.android.launcher3.dagger.LauncherComponentProvider;\nimport com.android.launcher3.util.TraceHelper;\n\npublic class LauncherApplication extends Application {\n\n    private volatile LauncherBaseAppComponent mAppComponent;\n    @Override\n    public void onCreate() {\n        super.onCreate();\n        LauncherComponentProvider.get(this).getMainProcessInitializer().init(this);\n    }',
        'import android.app.Application;\nimport android.content.Context;\nimport com.android.launcher3.dagger.DaggerLauncherAppComponent;\nimport com.android.launcher3.dagger.LauncherAppComponent;\nimport com.android.launcher3.dagger.LauncherBaseAppComponent;\nimport com.android.launcher3.dagger.LauncherComponentProvider;\nimport com.android.launcher3.util.TraceHelper;\nimport com.xaulinxs.customizations.theme.XaulinXsThemeColorResources;\nimport com.xaulinxs.customizations.theme.XaulinXsThemedContextWrapper;\n\npublic class LauncherApplication extends Application {\n\n    private volatile LauncherBaseAppComponent mAppComponent;\n\n    // XaulinXs Customizations — "UI-UX Custom Colors": envolve o Context\n    // base do processo com um wrapper que intercepta @color/materialColorX\n    // (ver XaulinXsThemeColorResources.kt para o porquê disso, em vez de\n    // tentar reescrever o XML empacotado no APK). Precisa ser attachBaseContext,\n    // não onCreate: getResources() já é chamado antes de onCreate rodar.\n    @Override\n    protected void attachBaseContext(Context base) {\n        super.attachBaseContext(new XaulinXsThemedContextWrapper(base));\n    }\n\n    @Override\n    public void onCreate() {\n        super.onCreate();\n        XaulinXsThemeColorResources.installIfEnabled(this);\n        LauncherComponentProvider.get(this).getMainProcessInitializer().init(this);\n    }',
    ),
    (
        "src/com/android/launcher3/Launcher.java",
        '    @Override\n    protected void attachBaseContext(Context base) {\n        super.attachBaseContext(base);\n        // XaulinXs Customizations: estende a fonte customizada (antes só\n        // aplicada aos labels dos ícones via BubbleTextView) para TODA\n        // TextView inflada nesta Activity',
        '    @Override\n    protected void attachBaseContext(Context base) {\n        // XaulinXs Customizations: "UI-UX Custom Colors" — mesma razão da\n        // fonte customizada logo abaixo (attachBaseContext é o ponto mais\n        // cedo em que dá pra interceptar Resources antes de qualquer\n        // inflação). O wrapper de Application (LauncherApplication) cobre\n        // getApplicationContext(), mas Activity.getResources() usa o\n        // Resources da própria Activity, que NÃO herda do wrapper da\n        // Application — por isso precisa ser instalado de novo aqui. Ver\n        // XaulinXsThemeColorResources.kt para detalhes.\n        super.attachBaseContext(new com.xaulinxs.customizations.theme.XaulinXsThemedContextWrapper(base));\n        // XaulinXs Customizations: estende a fonte customizada (antes só\n        // aplicada aos labels dos ícones via BubbleTextView) para TODA\n        // TextView inflada nesta Activity',
    ),
    (
        "src/com/android/launcher3/settings/SettingsActivity.java",
        '    @Override\n    protected void attachBaseContext(Context base) {\n        super.attachBaseContext(base);\n        // XaulinXs Customizations: mesma extensão de fonte customizada',
        '    @Override\n    protected void attachBaseContext(Context base) {\n        // XaulinXs Customizations: "UI-UX Custom Colors" — mesmo motivo\n        // documentado em Launcher.attachBaseContext: o Resources desta\n        // Activity não herda do wrapper instalado em LauncherApplication,\n        // então precisa ser instalado de novo aqui para que a tela de\n        // Configurações (e a própria CustomColorsActivity) já reflita a\n        // paleta customizada.\n        super.attachBaseContext(new com.xaulinxs.customizations.theme.XaulinXsThemedContextWrapper(base));\n        // XaulinXs Customizations: mesma extensão de fonte customizada',
    ),
    (
        "AndroidManifest.xml",
        '        <activity\n            android:name="com.xaulinxs.customizations.qsb.QsbConfigActivity"\n            android:theme="@style/HomeSettings.Theme"\n            android:label="@string/xaulinxs_qsb_config_title"\n            android:exported="false" />',
        '        <activity\n            android:name="com.xaulinxs.customizations.qsb.QsbConfigActivity"\n            android:theme="@style/HomeSettings.Theme"\n            android:label="@string/xaulinxs_qsb_config_title"\n            android:exported="false" />\n        <activity\n            android:name="com.xaulinxs.customizations.settings.CustomColorsActivity"\n            android:theme="@style/HomeSettings.Theme"\n            android:label="@string/xaulinxs_custom_colors_title"\n            android:exported="false" />',
    ),
    (
        "res/xml/launcher_preferences.xml",
        '        <Preference\n            android:key="xaulinxs_qsb_config"\n            android:title="@string/xaulinxs_qsb_config_title"\n            android:persistent="false">\n            <intent\n                android:targetPackage="com.android.launcher3"\n                android:targetClass="com.xaulinxs.customizations.qsb.QsbConfigActivity" />\n        </Preference>',
        '        <Preference\n            android:key="xaulinxs_qsb_config"\n            android:title="@string/xaulinxs_qsb_config_title"\n            android:persistent="false">\n            <intent\n                android:targetPackage="com.android.launcher3"\n                android:targetClass="com.xaulinxs.customizations.qsb.QsbConfigActivity" />\n        </Preference>\n\n        <Preference\n            android:key="xaulinxs_custom_colors"\n            android:title="@string/xaulinxs_custom_colors_title"\n            android:summary="@string/xaulinxs_custom_colors_summary"\n            android:persistent="false">\n            <intent\n                android:targetPackage="com.android.launcher3"\n                android:targetClass="com.xaulinxs.customizations.settings.CustomColorsActivity" />\n        </Preference>',
    ),
    (
        "res/values/xaulinxs_strings.xml",
        '    <!-- QSB Super Inteligente -->',
        '    <!-- UI-UX Custom Colors -->\n    <string name="xaulinxs_custom_colors_title">UI-UX Custom Colors</string>\n    <string name="xaulinxs_custom_colors_summary">Personaliza a cor primária (interruptores, botões, retângulos) e secundária (fundos, fontes) de todo o app</string>\n\n    <!-- QSB Super Inteligente -->',
    ),
]

patched, skipped_patch = [], []
for rel_path, old, new in PATCHES:
    target = Path(rel_path)
    if not target.exists():
        die(f"nao encontrei {rel_path}. O repo mudou de estrutura?")
    content = target.read_text(encoding="utf-8")

    # Idempotencia por patch: se o bloco NOVO ja esta no arquivo, este
    # patch especifico ja foi aplicado -- pula, independente de qualquer
    # outro marcador textual generico (que pode nao existir em todo
    # arquivo, ex.: AndroidManifest.xml/launcher_preferences.xml nao
    # contem literalmente "UI-UX Custom Colors").
    if new in content:
        skipped_patch.append(rel_path)
        continue

    if old not in content:
        die(
            f"nao encontrei o bloco esperado em {rel_path}.\n"
            "O arquivo pode ja ter sido editado manualmente de outro jeito. "
            "Abortando sem mexer em nada -- me manda o conteudo atual do "
            "arquivo que eu ajusto o patch."
        )

    content = content.replace(old, new)
    target.write_text(content, encoding="utf-8")
    patched.append(rel_path)

# ---------------------------------------------------------------------------
# Resumo
# ---------------------------------------------------------------------------
print()
if created:
    print("Arquivos criados:")
    for p in created:
        print("  +", p)
if skipped_new:
    print("Ja existiam (identicos, pulados):")
    for p in skipped_new:
        print("  =", p)
if patched:
    print("Arquivos com patch aplicado:")
    for p in patched:
        print("  ~", p)
if skipped_patch:
    print("Ja tinham o patch (pulados):")
    for p in skipped_patch:
        print("  =", p)

if not created and not patched:
    print()
    print("Ja aplicado -- nada a fazer.")
else:
    print()
    print("OK: UI-UX Custom Colors aplicado.")
    print("Agora: git add -A && git commit -m \'feat: UI-UX Custom Colors\' && git push")
    print("Depois: ./gradlew assembleNoQuickstepDebug")
